    if r.get('name') == 'gmail.show_inbox_threads':
        pristine_result = r.get('result')
        break

# Parse the pristine result
if isinstance(pristine_result, str):
    pristine_result = json.loads(pristine_result)

# Collect write information
write_info = []
for w in writes:
    write_info.append({
        'app': w.get('app'),
        'api': w.get('api'),
        'name': w.get('name'),
        'args': w.get('args'),
        'result': w.get('result')
    })

print(json.dumps({
    'queries': [],
    'facts': {
        'pristine_result_type': str(type(pristine_result)),
        'pristine_result_keys': list(pristine_result.keys()) if isinstance(pristine_result, dict) else 'not a dict',
        'pristine_result_length': len(pristine_result) if isinstance(pristine_result, (list, dict)) else None,
        'applied_writes': write_info
    }
}))
